use std::sync::atomic::{AtomicI32, Ordering};

mod counter {
    use std::sync::atomic::{AtomicI32, Ordering};
    pub static COUNT: AtomicI32 = AtomicI32::new(0);
    pub fn increment() {
        COUNT.fetch_add(1, Ordering::SeqCst);
    }
}

fn main() {
    println!("Count: {}", counter::COUNT.load(Ordering::SeqCst));
    counter::increment();
    println!("Incremented: {}", counter::COUNT.load(Ordering::SeqCst));
}

use std::sync::OnceLock;

static VERSION: OnceLock<String> = OnceLock::new();

fn main() {
    let v = VERSION.get_or_init(|| "1.0.0".into());
    println!("Version: {}", v);
}

